-- Migration: 078_add_solon_chagrin_falls_trail.sql
-- Description: Add Solon to Chagrin Falls Trail as a trail POI with OSM geometry.
--   A developing multi-use rail-trail on the former W&LE/NKP railroad corridor,
--   connecting Solon and Chagrin Falls via the Chagrin River valley.
--   Phase 1 (SOM Center Rd to Deer Run) opened October 2025.
--   Phase 2 (connecting to Chagrin River Rd) under construction 2026.
--   Future connection to the Headwaters Connector Greenway planned.

INSERT INTO pois (
  name,
  brief_description,
  poi_roles,
  latitude,
  longitude,
  primary_activities,
  geometry,
  more_info_link
)
